/*
 * T13-T18: src/core/btc.c against vectors generated by running SeedSigner's
 * own code (sim/vectors/seedsigner_core.h, scripts/vectors/). Each table is
 * named for the SeedSigner function it captures. Also runs on the device in
 * the QEMU self-test image.
 */
#include <stdlib.h>
#include <string.h>

#include "btc-init.h"
#include "btc.h"
#include "check.h"
#include "vectors/seedsigner_core.h"
#include "wally_bip39.h"
#include "wally_core.h"

#define N(a) (sizeof(a) / sizeof((a)[0]))

static void fake_rand(void *buf, unsigned len) { memset(buf, 0x42, len); }

static size_t unhex(const char *hex, uint8_t *out, size_t cap)
{
    size_t n = strlen(hex) / 2;
    if (n > cap) return 0;
    for (size_t i = 0; i < n; i++) {
        unsigned v;
        sscanf(hex + 2 * i, "%2x", &v);
        out[i] = (uint8_t)v;
    }
    return n;
}

static void hex(const uint8_t *b, size_t n, char *out)
{
    for (size_t i = 0; i < n; i++) sprintf(out + 2 * i, "%02x", b[i]);
    out[2 * n] = '\0';
}

static void join(const uint16_t *idx, size_t n, char *out)
{
    out[0] = '\0';
    for (size_t i = 0; i < n; i++) {
        if (i) strcat(out, " ");
        strcat(out, BIP39_WORDLIST[idx[i]]);
    }
}

/* Words to indexes; -1 if a word is unknown. */
static int split(const char *text, uint16_t *idx, size_t max)
{
    char buf[512];
    snprintf(buf, sizeof buf, "%s", text);
    int n = 0;
    for (char *t = strtok(buf, " ,"); t; t = strtok(NULL, " ,")) {
        int i = bip39_word_index(t);
        if (i < 0 || (size_t)n >= max) return -1;
        idx[n++] = (uint16_t)i;
    }
    return n;
}

static void test_wordlist(void)
{
    struct words *wl = NULL;
    CHECK(bip39_get_wordlist(NULL, &wl) == WALLY_OK, "wally wordlist");
    int bad = 0;
    for (int i = 0; i < BIP39_WORDS; i++) {
        char *w = NULL;
        bip39_get_word(wl, (size_t)i, &w);
        bad += !w || strcmp(w, BIP39_WORDLIST[i]) != 0 || bip39_word_index(w) != i;
        wally_free_string(w);
    }
    CHECK(bad == 0, "%d words differ from libwally's list", bad);
    CHECK(bip39_word_index("zzz") == -1 && bip39_word_index("") == -1, "non-words");
}

static void test_paths(void)
{
    char path[32];
    for (size_t i = 0; i < N(VEC_PATHS); i++) {
        const vec_path_t *v = &VEC_PATHS[i];
        bool ok = btc_standard_path(v->net, v->sig, v->script, path, sizeof path);
        if (v->path) CHECK(ok && strcmp(path, v->path) == 0, "path %zu: %s vs %s", i, ok ? path : "-", v->path);
        else CHECK(!ok, "path %zu should be refused, gave %s", i, path);
    }
}

static void test_xpubs(void)
{
    char xpub[120];
    for (size_t i = 0; i < N(VEC_XPUB); i++) {
        const vec_xpub_t *v = &VEC_XPUB[i];
        uint8_t seed[64];
        size_t len = unhex(v->seed_hex, seed, sizeof seed);
        bool ok = btc_xpub(seed, len, v->path, v->net, 0, xpub, sizeof xpub);
        CHECK(ok && strcmp(xpub, v->xpub) == 0, "xpub %zu %s\n    got  %s\n    want %s",
              i, v->path, ok ? xpub : "-", v->xpub);
    }
}

static void test_addresses(void)
{
    char addr[100];
    for (size_t i = 0; i < N(VEC_ADDR); i++) {
        const vec_addr_t *v = &VEC_ADDR[i];
        bool ok = btc_address(v->xpub, v->script, v->index, v->change, v->net, addr, sizeof addr);
        CHECK(ok && strcmp(addr, v->address) == 0, "address %zu (script %d, %s/%u)\n    got  %s\n    want %s",
              i, v->script, v->change ? "change" : "receive", v->index, ok ? addr : "-", v->address);
    }
    CHECK(!btc_address("xpubNOTBASE58", BTC_SCRIPT_P2WPKH, 0, false, BTC_NET_MAIN, addr, sizeof addr),
          "garbage xpub accepted");
}

static void test_export(void)
{
    char fp[9], path[32], out[160];
    seed_t s;
    for (size_t i = 0; i < N(VEC_EXPORT); i++) {
        const vec_export_t *v = &VEC_EXPORT[i];
        CHECK(seed_from_mnemonic(&s, v->mnemonic, v->passphrase) == SEED_OK, "seed %zu", i);
        seed_fingerprint_hex(&s, fp);
        CHECK(strcmp(fp, v->fingerprint) == 0, "fingerprint %zu: %s vs %s", i, fp, v->fingerprint);
        CHECK(btc_standard_path(v->net, v->sig, v->script, path, sizeof path) &&
              strcmp(path, v->path) == 0, "export path %zu", i);
        bool ok = btc_xpub_export(&s, v->path, v->net, out, sizeof out);
        CHECK(ok && strcmp(out, v->xpub_export) == 0, "export %zu %s\n    got  %s\n    want %s",
              i, v->path, ok ? out : "-", v->xpub_export);
        seed_clear(&s);
    }
}

static void test_seedqr(void)
{
    char words[400], digits[100], chex[70];
    for (size_t i = 0; i < N(VEC_SEEDQR); i++) {
        const vec_seedqr_t *v = &VEC_SEEDQR[i];
        uint8_t entropy[32], compact[32];
        uint16_t idx[24], back[24];
        size_t n = 0, len = unhex(v->entropy_hex, entropy, sizeof entropy);
        CHECK(mnemonic_from_entropy(entropy, len, idx, &n), "entropy %zu", i);
        join(idx, n, words);
        CHECK(strcmp(words, v->mnemonic) == 0, "mnemonic %zu", i);

        seed_t s;
        CHECK(seed_from_indices(&s, idx, n, "") == SEED_OK, "seed %zu", i);
        CHECK(seedqr_encode_standard(&s, digits, sizeof digits) && strcmp(digits, v->seedqr) == 0,
              "standard SeedQR %zu", i);
        size_t clen = seedqr_encode_compact(&s, compact);
        hex(compact, clen, chex);
        CHECK(strcmp(chex, v->compact_hex) == 0, "compact SeedQR %zu: %s vs %s", i, chex, v->compact_hex);

        CHECK(seedqr_decode_standard(v->seedqr, back) == n && memcmp(back, idx, n * 2) == 0,
              "standard decode %zu", i);
        uint8_t cbytes[32];
        size_t cb = unhex(v->compact_hex, cbytes, sizeof cbytes);
        CHECK(seedqr_decode_compact(cbytes, cb, back) == n && memcmp(back, idx, n * 2) == 0,
              "compact decode %zu", i);
        seed_clear(&s);
    }
    uint16_t idx[24];
    CHECK(seedqr_decode_standard("1234", idx) == 0, "short digits");
    CHECK(seedqr_decode_standard("204820482048204820482048204820482048204820482048", idx) == 0,
          "index 2048 is not a word");
    CHECK(seedqr_decode_standard("00000000000000000000000000000000000000000000000x", idx) == 0,
          "non-digit");
    uint8_t b[20] = { 0 };
    CHECK(seedqr_decode_compact(b, 20, idx) == 0, "20 bytes is not a compact SeedQR");
}

static void test_new_seeds(void)
{
    char words[400];
    uint16_t idx[24], out[24];
    size_t n;
    for (size_t i = 0; i < N(VEC_DICE); i++) {
        CHECK(mnemonic_from_dice(VEC_DICE[i].rolls, idx, &n), "dice %zu", i);
        join(idx, n, words);
        CHECK(strcmp(words, VEC_DICE[i].mnemonic) == 0, "dice %zu (%zu rolls)\n    got  %s\n    want %s",
              i, strlen(VEC_DICE[i].rolls), words, VEC_DICE[i].mnemonic);
    }
    CHECK(!mnemonic_from_dice("1234567", idx, &n), "a 7 is not a die face");

    for (size_t i = 0; i < N(VEC_CHECKSUM); i++) {
        const vec_checksum_t *v = &VEC_CHECKSUM[i];
        int k = split(v->partial, idx, 24);
        bool ok = k > 0 && mnemonic_complete_checksum(idx, (size_t)k, out, &n);
        if (v->mnemonic) {
            join(out, n, words);
            CHECK(ok && strcmp(words, v->mnemonic) == 0, "checksum %zu\n    got  %s\n    want %s",
                  i, ok ? words : "-", v->mnemonic);
        } else {
            CHECK(!ok, "checksum %zu should be refused: %s", i, v->partial);
        }
    }

    for (size_t i = 0; i < N(VEC_FLIPS); i++) {
        CHECK(mnemonic_from_coin_flips(VEC_FLIPS[i].flips, idx, &n), "flips %zu", i);
        join(idx, n, words);
        CHECK(strcmp(words, VEC_FLIPS[i].mnemonic) == 0, "coin flips %zu", i);
    }
    for (size_t i = 0; i < N(VEC_PARTIAL_WORD); i++) {
        int w = mnemonic_partial_final_word(VEC_PARTIAL_WORD[i].flips);
        CHECK(w >= 0 && strcmp(BIP39_WORDLIST[w], VEC_PARTIAL_WORD[i].word) == 0,
              "partial word %s", VEC_PARTIAL_WORD[i].flips);
    }
}

static void test_bip85(void)
{
    char words[400];
    uint16_t idx[24];
    size_t n;
    seed_t s;
    for (size_t i = 0; i < N(VEC_BIP85); i++) {
        const vec_bip85_t *v = &VEC_BIP85[i];
        CHECK(seed_from_mnemonic(&s, v->mnemonic, "") == SEED_OK, "seed");
        CHECK(bip85_child(&s, v->index, v->words, idx, &n), "bip85 %zu", i);
        join(idx, n, words);
        CHECK(strcmp(words, v->child) == 0, "bip85 %zu (index %u, %u words)\n    got  %s\n    want %s",
              i, v->index, v->words, words, v->child);
        seed_clear(&s);
    }
}

static void test_seed_errors(void)
{
    seed_t s;
    const char *ok12 = "abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon about";
    CHECK(seed_from_mnemonic(&s, ok12, "") == SEED_OK, "valid");
    CHECK(seed_from_mnemonic(&s, "ABANDON abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon About", "") == SEED_OK,
          "case-insensitive");
    CHECK(seed_from_mnemonic(&s, "abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon", "")
          == SEED_ERR_CHECKSUM, "bad checksum");
    CHECK(seed_from_mnemonic(&s, "abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abaut", "")
          == SEED_ERR_UNKNOWN_WORD, "unknown word");
    CHECK(seed_from_mnemonic(&s, "abandon abandon abandon", "") == SEED_ERR_WORD_COUNT, "3 words");
    CHECK(seed_from_mnemonic(&s, ok12, "caf\xc3\xa9") == SEED_ERR_PASSPHRASE, "non-ASCII passphrase");
    char longp[SEED_PASSPHRASE_MAX + 2];
    memset(longp, 'a', sizeof longp - 1);
    longp[sizeof longp - 1] = '\0';
    CHECK(seed_from_mnemonic(&s, ok12, longp) == SEED_ERR_PASSPHRASE, "overlong passphrase");
    longp[SEED_PASSPHRASE_MAX] = '\0';
    CHECK(seed_from_mnemonic(&s, ok12, longp) == SEED_OK, "passphrase at the limit");

    /* Passphrase changes the fingerprint, and back again. */
    char a[9], b[9], c[9];
    seed_from_mnemonic(&s, ok12, "");
    seed_fingerprint_hex(&s, a);
    CHECK(seed_set_passphrase(&s, "TREZOR") == SEED_OK, "set passphrase");
    seed_fingerprint_hex(&s, b);
    seed_set_passphrase(&s, "");
    seed_fingerprint_hex(&s, c);
    CHECK(strcmp(a, "73c5da0a") == 0 && strcmp(a, b) != 0 && strcmp(a, c) == 0, "passphrase round trip");

    char m[300];
    CHECK(seed_mnemonic(&s, m, sizeof m) && strcmp(m, ok12) == 0, "mnemonic text");
    CHECK(seed_mnemonic(&s, m, 20) == 0, "short buffer refused");

    seed_clear(&s);
    const uint8_t *p = (const uint8_t *)&s;
    size_t nonzero = 0;
    for (size_t i = 0; i < sizeof s; i++) nonzero += p[i] != 0;
    CHECK(nonzero == 0, "seed_clear left %zu bytes", nonzero);
}

int main(void)
{
    CHECK(btc_init(fake_rand), "btc_init");
    test_wordlist();
    test_paths();
    test_xpubs();
    test_addresses();
    test_export();
    test_seedqr();
    test_new_seeds();
    test_bip85();
    test_seed_errors();
    printf("  %zu paths, %zu xpubs, %zu addresses, %zu exports, %zu SeedQRs, %zu dice, "
           "%zu checksums, %zu BIP-85\n", N(VEC_PATHS), N(VEC_XPUB), N(VEC_ADDR), N(VEC_EXPORT),
           N(VEC_SEEDQR), N(VEC_DICE), N(VEC_CHECKSUM), N(VEC_BIP85));
    wally_cleanup(0);
    return CHECK_DONE("test_btc");
}
